def calculate_canopy_height_model(dsm_elev: float, dtm_elev: float) -> float:
    """Calculates normalized canopy/structure height CHM = max(0.0, DSM - DTM)."""
    h = float(dsm_elev) - float(dtm_elev)
    return round(max(0.0, h), 2)

